      { t: 'table', text: '', rows: [['実験１　光合成に植物が必要だということを確かめる実験 / 試験管A、Bを用意する。試験管Aにたんぽぽの葉を入れ、試験管Bには何も入れなかった。 / ①　息を吹き込んだ　　→　　試験管内の二酸化炭素の割合を増やすため / ②　石灰水を入れて振った　→　試験管内の二酸化炭素の割合を確認するため / 結果　試験管Ａ　石灰水は透明のままで変化がなかった　　　試験管Ｂ　石灰水は白くにごった / 実際に起こっていること：試験管Ａでは、たんぽぽの葉によって光合成が行われた（呼吸も行われているが、 / 呼吸の効果＜光合成の効果）ため、二酸化炭素の割合が減り、酸素の割合が増えた / 実験からわかること：　光合成には植物の葉が必要である / →実験による変化がたんぽぽの葉によるものだと区別するため、試験管Ａも準備をしている＝対照実験'], ['実験２　光合成に葉緑体が必要であることを確かめる実験 / たんぽぽの葉Ａ、Ｂ、を用意する。 / ①　Ａの葉をエタノールにつけた　　→　葉の色を脱色するため / エタノールは引火しやすいため、ガスバーナーなどで直接燃やしてはいけない / ②　Ａ、Ｂの葉にヨウ素液を垂らした　→　光合成が行われている場所を確認するため / 結果　試験管Ａ　ヨウ素液の色は変化しなかった　　　試験管Ｂ　ヨウ素液の色は青紫色に変化した / 実際に起こっていること：　エタノールによって、光合成に必要な葉緑体が取り除かれた / 実験からわかること：　光合成には葉緑体が必要である / →実験による変化が葉の緑色（葉緑体）であることを示すためにたんぽぽの葉Ｂを用意した＝対照実験'], ['実験３　光合成に日光が必要であることを確かめる実験 / 試験管Ａ、Ｂにたんぽぽの葉を入れる。 / ①　息を吹き込んだ　→　　試験管内の二酸化炭素の割合を増やすため / ②　試験管Ａのみ、試験管をアルミホイルで覆った　→　日光がたんぽぽの葉に当たらないようにするため / ➂　しばらく放置した後、石灰水を加えた　→　試験管内の二酸化炭素の割合を確認するため / 結果　試験管Ａ　石灰水は白くにごった　　試験管Ｂ　石灰水は透明なままで変化がなかった / 実際に起こっていること：　試験管Ａでは、日光が当たらなかったため、植物は光合成ができず呼吸のみを行った影響で試験管内の二酸化炭素の割合が増加したのに対し、試験管Ｂでは、日光が当たったため、植物は光合成を行い（呼吸の効果＜光合成の効果）、二酸化炭素の割合が減少して、酸素の割合が増加した / 実験からわかること：　光合成には日光が必要である / →実験による変化が日光の影響であることを示すためにたんぽぽの葉Ｂを用意した＝対照実験']] }
